<?php
session_start();require_once "config/conexao.php";$data=$_GET["data"]??date("Y-m-d");$st=$conn->prepare("SELECT f.id,f.data_frete,t.nome transportador,o.identificacao origem,d.identificacao destino,(SELECT GROUP_CONCAT(CONCAT(p.nome,' (',fp.quantidade,')') SEPARATOR ', ') FROM frete_produtos fp JOIN produtos p ON p.id=fp.produto_id WHERE fp.frete_id=f.id) produtos FROM fretes f JOIN transportadores t ON t.id=f.transportador_id JOIN enderecos o ON o.id=f.origem_id JOIN enderecos d ON d.id=f.destino_id WHERE f.data_frete=? ORDER BY f.id");$st->bind_param("s",$data);$st->execute();$lista=$st->get_result();$titulo="Relatórios";include "includes/cabecalho.php";?>
<div class="container py-4"><h1 class="h3">Relatório de fretes</h1><p class="text-muted">Escolha um dia para consultar e baixar os fretes.</p><div class="card border-0 shadow-sm"><div class="card-body"><form method="get" class="row g-2 align-items-end mb-4"><div class="col-md-4"><label class="form-label">Data</label><input type="date" name="data" value="<?= htmlspecialchars($data) ?>" class="form-control" required></div><div class="col-auto"><button class="btn btn-primary">Consultar</button></div><div class="col-auto"><a class="btn btn-outline-success" href="baixar_relatorio.php?data=<?= urlencode($data) ?>">Baixar CSV</a></div></form>
<p><strong><?= $lista->num_rows ?></strong> frete(s) encontrado(s) em <?= htmlspecialchars($data) ?>.</p><div class="table-responsive"><table class="table"><thead><tr><th>Nº</th><th>Transportador</th><th>Origem</th><th>Destino</th><th>Produtos</th></tr></thead><tbody><?php if($lista->num_rows):while($f=$lista->fetch_assoc()): ?><tr><td>#<?= $f["id"] ?></td><td><?= htmlspecialchars($f["transportador"]) ?></td><td><?= htmlspecialchars($f["origem"]) ?></td><td><?= htmlspecialchars($f["destino"]) ?></td><td><?= htmlspecialchars($f["produtos"]) ?></td></tr><?php endwhile;else: ?><tr><td colspan="5" class="text-muted">Nenhum frete nesta data.</td></tr><?php endif; ?></tbody></table></div></div></div></div><?php include "includes/rodape.php";?>